def _reinitialize_critic_output_layer(args: Namespace, model: Sequence[DDP]) -> None:
    # Same policy as `LinearForLastLayer.__init__`: a value head that has no
    # usable weights in the checkpoint (missing, or shaped like an actor LM
    # head) starts at V(s) = 0.  A random head of this size would produce the
    # same inflated first value loss and random advantage baseline.
    for _chunk_id, output_layer in _iter_critic_output_layers(model):
        output_layer.weight.data.zero_()
        if output_layer.bias is not None:
            output_layer.bias.data.zero_()

